function write(root=ROOT){const folder=path.join(root,'12-数据直报');let changed=0;for(const [type,name]of [['main','需求说明.md'],['sub','子页面与操作细化.md']]){const file=path.join(folder,name),before=fs.readFileSync(file,'utf8'),after=renderDocument(type,before);if(before!==after){fs.writeFileSync(file,after);changed++;}}return {changed,requirements:38};}
